#!/usr/bin/env python3
"""Command-line interface for the independently implemented secrets scanner."""
import difflib
import os
import sys
from scanner import scan, install_hooks, ScanError

OPTIONS = [
    ('--install-pre-commit', 'Install `ripsecrets` as a pre-commit hook automatically in git directory provided'),
    ('--strict-ignore', "If you pass a path as an argument that's ignored by .secretsignore it will be scanned by default. --strict-ignore will override this behavior and not search the paths passed as arguments that are excluded by the .secretsignore file. This is useful when invoking secrets as a pre-commit"),
    ('--only-matching', 'Print only the matched (non-empty) parts of a matching line, with each such part on a separate output line'),
    ('--additional-pattern <ADDITIONAL_PATTERNS>', 'Additional regex patterns used to find secrets. If there is a matching group in the regex the matched group will be tested for randomness before being reported as a secret'),
]
NAME = os.path.basename(sys.argv[0])
USAGE = f'Usage: {NAME} [OPTIONS] [Source files]...'
TRAILER = "For more information, try '--help'.\n"

def help_text(long):
    intro = ("ripsecrets searches files and directories recursively for secret API keys.\n"
             "It's primarily designed to be used as a pre-commit to prevent committing\n"
             "secrets into version control." if long else
             'A command-line tool to prevent committing secret keys into your source code')
    text = intro + '\n\n' + USAGE + '\n\nArguments:\n'
    text += ("  [Source files]...\n          " if long else "  [Source files]...  ")
    text += "Source files. Can be files or directories. Defaults to '.'\n\nOptions:\n"
    opts = [('    '+k, v) for k,v in OPTIONS]
    opts += [('-h, --help', "Print help (see a summary with '-h')" if long else "Print help (see more with '--help')"), ('-V, --version','Print version')]
    text += ('\n\n' if long else '\n').join('  '+k+'\n          '+v for k,v in opts)+'\n'
    return text

def cli_error(msg, usage=USAGE, tip=None):
    text = 'error: '+msg+'\n\n'
    if tip:
        text += '  tip: '+tip+'\n\n'
    if usage:
        text += usage+'\n\n'
    sys.stderr.write(text+TRAILER)
    return 2

def unexpected(arg):
    options = [k.split(' ')[0] for k,v in OPTIONS]+['--help','--version']
    similar = difflib.get_close_matches(arg, options, n=1, cutoff=0.7) if arg.startswith('--') else []
    if similar:
        tip = "a similar argument exists: '"+similar[0]+"'"
        usage = f'Usage: {NAME} <--install-pre-commit|--strict-ignore|--only-matching|--additional-pattern <ADDITIONAL_PATTERNS>|Source files>'
    else:
        tip = f"to pass '{arg}' as a value, use '-- {arg}'"
        usage = USAGE
    return cli_error(f"unexpected argument '{arg}' found", usage, tip)

def main():
    args = sys.argv[1:]
    paths, patterns, flags = [], [], set()
    literal = False
    i = 0
    while i < len(args):
        arg = args[i]
        i += 1
        if literal:
            paths.append(arg)
            continue
        if arg == '--':
            literal = True
            continue
        key, sep, value = arg.partition('=')
        if key in ('--help','--version'):
            if sep:
                return cli_error(f"unexpected value '{value}' for '{key}' found; no more were expected", f'Usage: {NAME} {key}')
            sys.stdout.write(help_text(True) if key=='--help' else 'ripsecrets 0.1.11\n')
            return 0
        if arg.startswith('-') and not arg.startswith('--') and arg!='-':
            for c in arg[1:]:
                if c in 'hV':
                    sys.stdout.write(help_text(False) if c=='h' else 'ripsecrets 0.1.11\n')
                    return 0
                return unexpected('-'+c)
        if key in ('--install-pre-commit','--strict-ignore','--only-matching'):
            if sep:
                return cli_error(f"unexpected value '{value}' for '{key}' found; no more were expected", f'Usage: {NAME} {key} [Source files]...')
            if key in flags:
                return cli_error(f"the argument '{key}' cannot be used multiple times")
            flags.add(key)
        elif key == '--additional-pattern':
            if not sep:
                if i >= len(args) or args[i].startswith('--'):
                    return cli_error("a value is required for '--additional-pattern <ADDITIONAL_PATTERNS>' but none was supplied", None)
                value = args[i]
                i += 1
                if value.startswith('-') and value!='-':
                    return unexpected(value if value.startswith('--') else value[:2])
            patterns.append(value)
        elif arg.startswith('--'):
            return unexpected(key)
        else:
            paths.append(arg)
    try:
        if '--install-pre-commit' in flags:
            install_hooks(paths or ['.'])
            return 0
        return scan(paths or ['.'], patterns, '--only-matching' in flags, '--strict-ignore' in flags)
    except ScanError as exc:
        sys.stderr.write('Error: '+str(exc)+'\n')
        return 2
    except BrokenPipeError:
        return 0

if __name__ == '__main__':
    sys.exit(main())
