"""Random-looking captured value classification."""
import collections
import math

def is_random(value):
    n = len(value)
    if n <= 2:
        return True
    if len(set(value)) == 1:
        return value == '999'
    count = collections.Counter(value)
    entropy = -sum((v/n)*math.log2(v/n) for v in count.values())
    if n < 15:
        return entropy >= math.log2(n)*0.77 and not (value.isdecimal() and n < 13)
    if all(c in '0123456789abcdefABCDEF' for c in value):
        return entropy >= 3.0 and entropy >= min(3.45, math.log2(n)*0.77)
    lower = sum(c.islower() for c in value)
    upper = sum(c.isupper() for c in value)
    digit = sum(c.isdigit() for c in value)
    if lower == n:
        return False
    if upper == n:
        return n <= 30 and entropy >= 3.7
    if lower+upper == n and n > 36:
        return False
    if entropy < min(4.0,math.log2(n)*0.8):
        return False
    transitions = sum((a.islower(),a.isupper(),a.isdigit()) != (b.islower(),b.isupper(),b.isdigit()) for a,b in zip(value,value[1:]))
    return transitions >= 2 or not value.isalnum()
