    expr=expr.replace(r'\z',r'\Z')
    # POSIX character classes.
    for name,p in [('alnum','A-Za-z0-9'),('alpha','A-Za-z'),('digit','0-9'),('xdigit','A-Fa-f0-9'),('lower','a-z'),('upper','A-Z'),('word',r'A-Za-z0-9_'),('space',r'\s'),('blank',r' \t'),('ascii',r'\x00-\x7f')]:
        expr=expr.replace('[:'+name+':]',p)
    out=[]; stack=[0]; i=0; inclass=False
    while i<len(expr):
        c=expr[i]
        if c=='\\' and i+1<len(expr):
            out.append(expr[i:i+2]);i+=2;continue
        if c=='[':inclass=True
        if c==']':inclass=False
        if c=='(' and not inclass:
            f=re.match(r'\(\?([imsxURu-]+)([:)])',expr[i:])
            if f:
                flags=f.group(1);close=f.group(2)
                disable_u='-u' in flags
                flags=flags.replace('U','').replace('R','').replace('u','').strip('-')
                if disable_u: flags='a'+flags
                if close==')':
                    out.append('(?'+flags+':' if flags else '(?:');stack[-1]+=1
                else:
                    out.append('(?'+flags+':' if flags else '(?:');stack.append(0)
                i+=f.end();continue
            # Rust accepts (?<name>...) as well as (?P<name>...).
            if expr.startswith('(?<',i) and not expr.startswith(('(?<=','(?<!'),i):
                out.append('(?P<');i+=3;stack.append(0);continue
            stack.append(0)
        elif c==')' and not inclass:
            extra=stack.pop() if len(stack)>1 else 0
            out.append(')'*extra)
        out.append(c);i+=1
    out.append(')'*stack[0])
    return ''.join(out)

def compile_pattern(extras):
    combined = '('+'|'.join(PATTERNS+extras)+')'
    # Diagnose constructs unsupported by the observed regex language.
    for p, message, n in [
        (r'\(\?<[=!]','look-around, including look-ahead and look-behind, is not supported',4),
        (r'\(\?[=!]','look-around, including look-ahead and look-behind, is not supported',3),
        (r'(?<!\\)\\[1-9]','backreferences are not supported',2),
    ]:
        m=re.search(p,combined)
        if m:
            raise ScanError(regex_diagnostic(combined,m.start(),n,message))
    try:
        return re.compile(translate_regex(combined))
    except re.error as exc:
        msg=str(exc); pos=exc.pos or 0;length=1
        if 'unterminated character set' in msg:
            text='unclosed character class'
        elif 'unterminated subpattern' in msg:
            text='unclosed group'
        elif 'unbalanced parenthesis' in msg:
            text='unopened group'
        elif 'nothing to repeat' in msg:
            text='repetition operator missing expression'
        elif 'bad character range' in msg:
            text='invalid character class range, the start must be <= the end';length=3
        elif 'min repeat greater' in msg:
            text='invalid repetition count range, the start must be <= the end'
            pos=combined.rfind('{',0,pos+1) if combined[pos:pos+1]!='{' else pos
            length=combined.find('}',pos)-pos+1
        elif 'bad escape' in msg:
            text='unrecognized escape sequence';length=2
        elif 'unknown extension' in msg:
            text='unrecognized flag';pos+=1
        elif 'redefinition of group name' in msg:
            text='duplicate capture group name'
        else:
            text=msg.split(' at position')[0]
        raise ScanError(regex_diagnostic(combined,pos,length,text))

class Matcher:
    def __init__(self, extras, ignored):
        self.regex=compile_pattern(extras)
        self.ignored=ignored
        self.cache={}

    def find(self,text,start=0,end=None):
        if end is None:end=len(text)
        cursor=start
        while cursor<=end:
            m=self.regex.search(text,cursor,end)
            if m is None:return None
            idx=1
            for j in range(2,len(m.groups())+1):
                if m.start(j)!=-1:
                    idx=j;break
            left,right=m.span(idx)
            value=m.group(idx)
            okay=value not in self.ignored
            if okay and idx>1:
                if value not in self.cache:self.cache[value]=is_random(value)
                okay=self.cache[value]
            if okay:
                return left,right
            cursor=right if right>cursor else cursor+1
        return None

class IgnoreRule:
    def __init__(self,line,base):
        self.base=base
        self.negate=False
        self.dironly=False
        self.regex=None
        s=line.rstrip('\r')
        # Ignore unescaped trailing spaces, as in a gitignore file.
        s=re.sub(r'(?<!\\) +$','',s)
        if not s or s[0]=='#':return
        if s[0]=='!':
            self.negate=True;s=s[1:]
        if not s:return
        if s.endswith('/'):
            self.dironly=True;s=s[:-1]
        anchored=s.startswith('/')
        if anchored:s=s[1:]
        self.basename=not anchored and '/' not in s
        self.pattern=s
        i=0;out='';brace=0
        while i<len(s):
            c=s[i]
            if c=='\\':
                i+=1
                if i>=len(s):raise ValueError("dangling '\\'")
                out+=re.escape(s[i])
            elif c=='*':
                j=i
                while j<len(s) and s[j]=='*':j+=1
                if j-i>=2 and (i==0 or s[i-1]=='/') and (j==len(s) or s[j]=='/'):
                    if j<len(s):out+='(?:.*/)?';j+=1
                    else:out+='.*'
                else:out+='[^/]*'
                i=j-1
            elif c=='?':out+='[^/]'
            elif c=='[':
                j=i+1
                if j<len(s) and s[j] in '!^':j+=1
                if j<len(s) and s[j]==']':j+=1
                while j<len(s) and s[j]!=']':j+=1
                if j==len(s):raise ValueError("unclosed character class; missing ']' ")
                cl=s[i+1:j]
                if cl.startswith('!'):cl='^'+cl[1:]
                for m in re.finditer(r'(.)-(.)',cl):
                    if ord(m[1])>ord(m[2]):raise ValueError(f"invalid range; '{m[1]}' > '{m[2]}'")
                out+='['+cl+']';i=j
            elif c=='{':out+='(?:';brace+=1
            elif c=='}' and brace:out+=')';brace-=1
            elif c==',' and brace:out+='|'
            else:out+=re.escape(c)
            i+=1
        if brace:raise ValueError("unclosed alternate group; missing '}' (maybe escape '{' with '[{]'?)")
        try:self.regex=re.compile('^'+out+'$')
        except re.error:self.regex=None
    def matches(self,path,isdir):
        if self.regex is None or self.dironly and not isdir:return False
        try:rel=os.path.relpath(path,self.base).replace(os.sep,'/')
        except ValueError:return False
        if rel=='..' or rel.startswith('../'):return False
        target=rel.rsplit('/',1)[-1] if self.basename else rel
        return self.regex.fullmatch(target) is not None

def read_rules(path,base=None,content=None,errors=None):
    if base is None:base=os.path.dirname(path)
    try:
        if content is None:
            with open(path,'r',encoding='utf-8',errors='replace') as f:content=f.read()
    except OSError:return []
    rules=[]
    for i,line in enumerate(content.splitlines(),1):
        try:
            rules.append(IgnoreRule(line,base))
        except ValueError as exc:
            if errors is not None:
                errors.append(f"{path}: line {i}: error parsing glob '{line}': {str(exc).rstrip()}\n")
    return rules

def rule_state(rules,path,isdir):
    state=None
    for rule in rules:
        if rule.matches(path,isdir):state=not rule.negate
    return state

def parents(path):
    path=os.path.abspath(path)
    chain=[]
    while True:
        chain.append(path)
        p=os.path.dirname(path)
        if p==path:break
        path=p
    return list(reversed(chain))

class Walker:
    def __init__(self,secret_rules,strict,config_errors):
        self.secret_rules=secret_rules
        self.strict=strict
        self.config_errors=config_errors
        self.gitcache={}
    def root_ignored(self,path,isdir):
        chain=parents(path)
        for i,p in enumerate(chain):
            if rule_state(self.secret_rules,p,i<len(chain)-1 or isdir) is True:return True
        return False
    def initial_rules(self,path):
        base=path if os.path.isdir(path) else os.path.dirname(path)
        chain=parents(base)
        git=any(os.path.exists(os.path.join(d,'.git')) for d in chain)
        gr=[];ir=[]
        for d in chain[:-1]:
            if git:gr+=read_rules(os.path.join(d,'.gitignore'))
            ir+=read_rules(os.path.join(d,'.ignore'))
        if git:
            for d in chain:
                if os.path.exists(os.path.join(d,'.git')):
                    gr=read_rules(os.path.join(d,'.git','info','exclude'),d)+gr
        return gr,ir,git
    def walk(self,paths):
        for original in paths:
            if original=='-':continue
            if original=='':original=''
            try:
                st=os.stat(original)
            except OSError as exc:
                sys.stderr.write(f'{original}: {os_error(exc)}\n');continue
            path=original.rstrip('/') or '/'
            if self.strict and self.root_ignored(os.path.abspath(path),stat.S_ISDIR(st.st_mode)):continue
            if stat.S_ISREG(st.st_mode):
                yield path
                continue
            if not stat.S_ISDIR(st.st_mode):continue
            for err in self.config_errors:
                sys.stderr.write(err);sys.stderr.write(err)
            gr,ir,git=self.initial_rules(os.path.abspath(path))
            yield from self.walk_dir(path,gr,ir,git)
    def walk_dir(self,path,git_rules,ignore_rules,git):
        ab=os.path.abspath(path)
        git=git or os.path.exists(os.path.join(ab,'.git'))
        if git:git_rules=git_rules+read_rules(os.path.join(ab,'.gitignore'))
        ignore_rules=ignore_rules+read_rules(os.path.join(ab,'.ignore'))
        try:
            entries=list(os.scandir(path))
        except OSError as exc:
            sys.stderr.write(f'{path}: {os_error(exc)}\n');return
        for entry in reversed(entries):
            try:
                if entry.is_symlink():continue
                directory=entry.is_dir(follow_symlinks=False)
                regular=entry.is_file(follow_symlinks=False)
                if not directory and not regular:continue
                state=None
                absolute=os.path.abspath(entry.path)
                for rules in (git_rules,ignore_rules,self.secret_rules):
                    s=rule_state(rules,absolute,directory)
                    if s is not None:state=s
                if state is True or state is None and entry.name.startswith('.'):continue
                if directory:
                    yield from self.walk_dir(entry.path,git_rules,ignore_rules,git)
                else:yield entry.path
            except OSError as exc:
                sys.stderr.write(f'{entry.path}: {os_error(exc)}\n')

def decode_file(raw):
    if raw.startswith(codecs.BOM_UTF8):return raw[3:].decode('utf-8','surrogateescape')
    if raw.startswith(codecs.BOM_UTF16_LE):return raw[2:].decode('utf-16-le','replace')
    if raw.startswith(codecs.BOM_UTF16_BE):return raw[2:].decode('utf-16-be','replace')
    return raw.decode('utf-8','surrogateescape')

def scan(paths,patterns,only_matching,strict):
    # Validate regular expressions before beginning traversal.
    matcher=Matcher(patterns,set())
    cfg=os.path.join(os.getcwd(),'.secretsignore')
    contents=''
    try:
        with open(cfg,'rb') as f:contents=f.read().decode('utf-8')
    except FileNotFoundError:pass
    except UnicodeDecodeError:raise ScanError('stream did not contain valid UTF-8')
    except OSError as exc:raise ScanError(os_error(exc))
    sections=contents.split('[secrets]\n')
    ignored=set(sections[1].split('\n')) if len(sections)>1 else set()
    matcher.ignored=ignored
    errors=[]
    rules=read_rules(cfg,os.getcwd(),sections[0],errors)
    walker=Walker(rules,strict,errors)
    found=False
    for path in walker.walk(paths):
        try:
            with open(path,'rb') as f:raw=f.read()
        except OSError as exc:
            sys.stderr.write(f'{path}: {os_error(exc)}\n');continue
        data=decode_file(raw)
        outputs=[];position=0
        for number,line in enumerate(data.split('\n'),1):
            end=position+len(line)
            if end==len(data) and not line:break
            if 'pragma: allowlist secret' not in line and matcher.find(line) is not None:
                found=True
                prefix=f'{path}:{number}:'
                if only_matching:
                    at=position;count=0
                    while at<end:
                        match=matcher.find(data,at,end)
                        if match is None:break
                        a,b=match
                        outputs.append(prefix+data[a:b]+'\n');count+=1
                        at=b if b>at else at+1
                    if count==0:outputs.append(prefix+line+'\n')
                else:
                    outputs.append(prefix+line+'\n')
            position=end+1
        if outputs:
            sys.stdout.buffer.write(''.join(outputs).encode('utf-8','surrogateescape'))
            sys.stdout.buffer.flush()
    return 1 if found else 0
