    r'https://hooks\.slack\.com/services/T[\dA-Za-z_]+/B[\dA-Za-z_]+/[\dA-Za-z_]+',
    r'SG\.[\dA-Za-z_-]{22}\.[\dA-Za-z_-]{43}',
    r'(?:AC|SK)[\da-z]{32}',
    r'[\da-f]{32}-us\d{1,2}',
    r's-s4t2(?:af|ud)-[\da-f]{64}',
    r'PuTTY-User-Key-File-2',
    r'AGE-SECRET-KEY-1[\dA-Z]{58}',
] + [r'-{5}BEGIN '+kind+r'-{5}(?:$|[^-]{63,}-{5}END)' for kind in [
    'DSA PRIVATE KEY', 'EC PRIVATE KEY', 'OPENSSH PRIVATE KEY',
    'PGP PRIVATE KEY BLOCK', 'PRIVATE KEY', 'RSA PRIVATE KEY',
    'SSH2 ENCRYPTED PRIVATE KEY',
