def os_error(exc):
    return f'{exc.strerror} (os error {exc.errno})'

def install_hooks(paths):
    for path in paths:
        gitdir = os.path.join(path,'.git')
        if not os.path.exists(gitdir):
            raise ScanError('.git directory not found')
        hook = os.path.join(gitdir,'hooks','pre-commit')
        try:
            exists = os.path.exists(hook)
            previous = open(hook,'rb').read() if exists else b''
            try:
                previous.decode('utf-8')
            except UnicodeDecodeError:
                raise ScanError('stream did not contain valid UTF-8')
            if HOOK in previous:
                raise ScanError('pre-commit hook has already been installed')
            with open(hook,'ab') as f:
                f.write(HOOK)
            if not exists:
                os.chmod(hook,0o744)
