            raise ScanError(os_error(exc))

def regex_diagnostic(pattern, pos, length, message):
    return 'regex parse error:\n    '+pattern+'\n'+' '*(4+pos)+'^'*max(1,length)+'\nerror: '+message

def translate_regex(expr):
